type Status = "OPEN" | "IN_PROGRESS" | "CLOSED";
const icons: Record<Status, string> = { OPEN: "🟢", IN_PROGRESS: "🟡", CLOSED: "⚪" };
export function StatusIcon({ status }: { status: Status }) { return <span title={status}>{icons[status]}</span>; }

type Status = "OPEN" | "IN_PROGRESS" | "CLOSED";
const labels: Record<Status, string> = { OPEN: "Otwarty", IN_PROGRESS: "W toku", CLOSED: "Zamknięty" };
export function StatusLabel({ status }: { status: Status }) { return <p>{labels[status]}</p>; }

type State = { status: "loading" } | { status: "error"; error: string } | { status: "success"; data: string[] };
export function Results({ state }: { state: State }) {
  if (state.status === "loading") return <p>Ładowanie</p>;
  if (state.status === "error") return <p role="alert">Błąd: {state.error}</p>;
  if (state.data.length === 0) return <p>Brak ticketów</p>;
  return <p>Wyniki: {state.data.length}</p>;
}

import type { ReactNode } from "react";
type View = "list" | "details";
const panels: Record<View, ReactNode> = { list: <p>Lista</p>, details: <p>Szczegóły</p> };
export function Content({ view }: { view: View }) { return <section>{panels[view]}</section>; }

type Ticket = { id: number; title: string; priority: "LOW" | "MEDIUM" | "HIGH" | "CRITICAL"; assignee: string | null; tags: string[] };
export function TicketCard({ ticket }: { ticket: Ticket | null }) {
  if (ticket === null) return <p>Wybierz ticket z listy</p>;
  const urgent = ticket.priority === "HIGH" || ticket.priority === "CRITICAL";
  return <article><h3>{urgent && <span aria-label="pilne">⚠</span>}#{ticket.id} {ticket.title}</h3><p>{ticket.assignee === null ? "Nieprzypisany" : `Przypisany: ${ticket.assignee}`}</p>{ticket.tags.length > 0 && <p>Tagi: {ticket.tags.join(", ")}</p>}</article>;
}

